import{_ as t,o as e,c as a,Q as r}from"./chunks/framework.b67c47e6.js";const f=JSON.parse('{"title":"BVX File (Hundegger Wood Profiles)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/machine_files/formats/wood_bvx/index.md","filePath":"guide/machine_files/formats/wood_bvx/index.md","lastUpdated":1793787262000}'),o={name:"guide/machine_files/formats/wood_bvx/index.md"},n=r('<h1 id="bvx-file-hundegger-wood-profiles" tabindex="-1">BVX File (Hundegger Wood Profiles) <a class="header-anchor" href="#bvx-file-hundegger-wood-profiles" aria-label="Permalink to &quot;BVX File (Hundegger Wood Profiles)&quot;">​</a></h1><p>The BVX format generates advanced wood profile cutting data for Hundegger machines. It offers more features than BTL, including material splitting, bench orientation, and void operations.</p><nav class="table-of-contents"><ul><li><a href="#output">Output</a></li><li><a href="#parameters">Parameters</a><ul><li><a href="#user-attributes">User Attributes</a></li></ul></li><li><a href="#marks">Marks</a></li><li><a href="#longitudinal-cuts">Longitudinal cuts</a></li><li><a href="#drillings">Drillings</a></li></ul></nav><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> ZIP containing <code>.bvx</code> files</li><li><strong>Target machines:</strong> Hundegger Speed-Cut, Hundegger Turbo-Drive</li></ul><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><table><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Group parts from the report in the same folder</strong></td><td>How to organize output files: &#39;By Panel&#39;, &#39;By Batch&#39;, or &#39;By Phase&#39;.</td><td>By Panel</td></tr><tr><td><strong>Split shared references per panel (By Batch / By Phase)</strong></td><td>Only when grouping By Batch or By Phase. Keeps a reference that appears in several panels as one entry per panel instead of merging them.</td><td>Off</td></tr><tr><td><strong>Split files options</strong></td><td>&#39;No split&#39;, &#39;Split by materials&#39;, or &#39;Split by materials and sizes&#39;.</td><td>No split</td></tr><tr><td><strong>Part orientation</strong></td><td>Orientation of the part on the machine bench: &#39;Horizontal&#39; or &#39;Vertical&#39;.</td><td>Vertical</td></tr><tr><td><strong>Use voids</strong></td><td>Include void/cutout operations in the output.</td><td>Off</td></tr><tr><td><strong>Create Marks on parts</strong></td><td>Mark the position of each stud on the top and bottom rails. See <a href="#marks">Marks</a>.</td><td>Off</td></tr><tr><td><strong>Print the stud reference at each mark</strong></td><td>With marks on, also print the reference of each stud between its two lines. Needs an inkjet on the machine.</td><td>Off</td></tr><tr><td><strong>Include longitudinal cuts</strong></td><td>Bevels, rips, rebates and grooves that run along the part. See <a href="#longitudinal-cuts">Longitudinal cuts</a>.</td><td>Off</td></tr><tr><td><strong>Number of decimals in angles</strong></td><td>Number of decimal places for angle values.</td><td>1</td></tr><tr><td><strong>Reference prefixes to filter</strong></td><td>Only include parts whose reference starts with one of the prefixes in the table.</td><td>—</td></tr></tbody></table><h3 id="user-attributes" tabindex="-1">User Attributes <a class="header-anchor" href="#user-attributes" aria-label="Permalink to &quot;User Attributes&quot;">​</a></h3><p>You can define up to 5 custom attributes embedded in the BVX file, each with a <strong>name</strong> and <strong>value</strong> field.</p><p>The value is a template: free text plus <strong>properties</strong> in curly braces, replaced per part — <code>{part_pos}</code>, <code>{assembly_name}</code>, <code>{material}</code>, your own model properties, and so on. The <strong>Insert property</strong> button on the field lists everything it accepts, and the full list is in <strong><a href="/guide/properties/">Properties in texts</a></strong>.</p><h2 id="marks" tabindex="-1">Marks <a class="header-anchor" href="#marks" aria-label="Permalink to &quot;Marks&quot;">​</a></h2><p>With <strong>Create Marks on parts</strong> on, every top and bottom rail gets the layout of the studs standing on it, as in the BTL file. Studs with an angled head or a chamfered foot are marked too:</p><ul><li>two lines across the rail at the edges of each stud, on the rail face the studs sit against;</li><li>with <strong>Print the stud reference at each mark</strong>, the stud reference printed between the two lines.</li></ul><p>The machine needs a marking tool for the lines and an inkjet for the text; without them it reports that no suitable tool was found. The height of the text on the rail is set on the machine (the inkjet position), not in the file.</p><h2 id="longitudinal-cuts" tabindex="-1">Longitudinal cuts <a class="header-anchor" href="#longitudinal-cuts" aria-label="Permalink to &quot;Longitudinal cuts&quot;">​</a></h2><p>With <strong>Include longitudinal cuts</strong> on, material removed along the length of a part reaches the machine too. It is read from the part&#39;s own shape:</p><ul><li><strong>A bevel or a rip over the whole length</strong> — a chamfered edge, or a strip cut off along the part — is cut <strong>by saw</strong>, along the part, and the strip comes off as an offcut.</li><li><strong>A bevel or a rip over part of the length</strong> is <strong>milled</strong>. A saw cut that stops inside the part would leave the strip attached at that end.</li><li><strong>A rebate or a square groove</strong> along the part is milled.</li></ul><p>Each one is placed on the face that holds it best: the one the cut stands squarest to, and on a tie the top, then the front.</p><p>When the shape already comes as an opening in the model, it is cut once, from the opening.</p><p>Not exported yet: V-shaped grooves, shapes that do not reach the surface of the part, and rebates or grooves whose sides are not square to each other. Each one left out is listed in the errors file of the export.</p><h2 id="drillings" tabindex="-1">Drillings <a class="header-anchor" href="#drillings" aria-label="Permalink to &quot;Drillings&quot;">​</a></h2><p>Holes are written as <code>Drilling</code> operations on the face they enter from.</p><ul><li>A hole whose depth matches the thickness of the part along the drilling axis (within 1 mm) is written as a <strong>through-hole</strong> (<code>Depth=&quot;0&quot;</code>), so the machine drills all the way through even when the real timber is slightly thicker than the model.</li><li>Any other hole keeps its measured depth as a blind hole.</li><li>On I-beams, holes through the web are always written as through-holes.</li><li>Holes running along the length of the part are not exported.</li></ul>',23),s=[n];function i(l,d,h,u,g,p){return e(),a("div",null,s)}const m=t(o,[["render",i]]);export{f as __pageData,m as default};
